"""Offline review dashboard: escaped content, local filtering, no send actions."""
import html
import json
import urllib.parse


def render(report):
    e = lambda v: html.escape(str(v) if v is not None else '—', quote=True)
    if report.get('status') == 'discovery_failed':
        return '<!doctype html><html lang="en"><meta charset="utf-8"><title>Discovery failed</title><h1>Discovery failed — research incomplete</h1><p>' + e(report.get('message', '')) + '</p><pre>' + e(json.dumps(report.get('discovery', {}), indent=2)) + '</pre></html>'
    def link(url, label=None):
        p = urllib.parse.urlsplit(str(url))
        if p.scheme not in ('http', 'https') or not p.hostname or p.username or p.password:
            return e(label or url)
        return f'''<a href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(label or url)}</a>'''
    def issue(f):
        confirmed = f.get('status') == 'verified'
        return f'''<li class="finding"><span class="tag {"verified" if confirmed else "potential"}">{"Verified" if confirmed else "Browser inspection needed"}</span><p>{e(f["observation"])}</p><p class="muted">{e(f.get("action", "Review the evidence before outreach."))}</p><details><summary>Evidence and source</summary><p>{link(f["url"])}</p><pre>{e(f['evidence'])}</pre><p>Observed on {len(f.get('sources', [f['url']]))} page(s).</p><pre>{e(json.dumps(f.get('evidence_records', []), indent=2))}</pre></details></li>'''
    cards = []
    for index, lead in enumerate(sorted(report.get('new_leads', []), key=lambda l: -l.get('ranking', {}).get('score', 0)), 1):
        ranking = lead.get('ranking', {})
        contacts = ''.join(f'<li>{e(c["kind"].title())}: <strong>{e(c["value"])}</strong><span class="muted"> · {" · ".join(link(s, "source") for s in c.get("sources", [c.get("source", "")]))}</span></li>' for c in lead['contacts'])
        fit = lead.get('fit', {})
        fit_html = '<p class="muted">Business fit: ' + e(fit.get('ownership', 'unknown')) + ' · ' + e('; '.join(fit.get('reasons', []))) + '</p>'
        related = '<p class="muted">Related identities sharing this issue: ' + ' · '.join(link(r['website'],r['name']) for r in lead.get('related_businesses', [])) + '</p>' if lead.get('related_businesses') else ''
        draft = lead.get('draft')
        draft_html = f'<section class="draft"><h3>Outreach draft · never sent</h3><label>Subject<input readonly value="{e(draft["subject"])}"></label><label>Message<textarea readonly rows="12">{e(draft["body"])}</textarea></label><button type="button" class="copy">Copy message</button><span class="copy-status" role="status"></span></section>' if draft else '<p>No outreach draft: this record requires further review.</p>'
        coverage = lead.get('coverage', {})
        pages = ''.join(f'<li>{link(p["url"])} · {e(p["forms"])} forms · {e(p["cta_links"])} contact CTAs · {len(p.get("booking_links", []))} booking links</li>' for p in coverage.get('pages', []))
        cards.append(f'''<article class="prospect" data-name="{e(lead["name"].lower())}"><header><div><p class="eyebrow">Priority {index} · {e(ranking.get("priority", "Review"))}</p><h2>{e(lead["name"])}</h2><p>{e(lead.get("category", ""))} · {link(lead["website"], "Visit website")}</p></div><div class="score">{e(ranking.get("score", "—"))}<small>/ 100</small></div></header><p class="muted">{e(ranking.get("reason", "Historical report; no new ranking assigned."))}</p><div class="columns"><section><h3>Why this prospect</h3>{fit_html}{related}<ul class="issues">{"".join(issue(f) for f in lead["findings"])}</ul><h3>Public contacts</h3><ul>{contacts}</ul><details><summary>Inspection coverage and discovery</summary><ul>{pages}</ul><p>Browser verification: {e(coverage.get('browser', {}).get('status', 'not attempted'))}</p><p>{e('; '.join(coverage.get('limitations', [])))}</p><details><summary>Browser observations</summary><pre>{e(json.dumps(coverage.get('browser', {}), indent=2))}</pre></details><p>Discovery: {link(lead.get("discovery_source", ""))}</p><p>Checked: {e(lead.get("checked_at", ""))}</p></details></section>{draft_html}</div></article>''')
    queue = []
    for lead in report.get('review_queue', []):
        related = '<p>Related identities: ' + ' · '.join(link(r['website'],r['name']) for r in lead.get('related_businesses', [])) + '</p>' if lead.get('related_businesses') else ''
        queue.append(f'''<details class="review-item"><summary>{e(lead["name"])} · {len(lead["findings"])} possible issue(s) · no draft</summary><p>{link(lead['website'])}</p>{related}<p class="muted">Fit: {e(lead.get('fit', {}).get('ownership', 'unknown'))}</p><ul class="issues">{"".join(issue(f) for f in lead["findings"])}</ul></details>''')
    exclusions = '<details><summary>Excluded businesses and retained related identities</summary><ul>' + ''.join('<li>' + e(x['name']) + ': ' + e('; '.join(x['fit']['reasons'])) + '</li>' for x in report.get('excluded_businesses', [])) + ''.join('<li>' + link(x['entity']['website'], x['entity']['name']) + ': ' + e(x['reason']) + '</li>' for x in report.get('related_identities', [])) + '</ul></details>'
    discovery = report.get('discovery', {})
    diagnostics = '<pre>' + e(json.dumps(discovery, indent=2)) + '</pre>' if report.get('status') == 'discovery_failed' else ''
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Fouse Digital · Prospect review</title><style>
:root{color-scheme:light;--ink:#182d38;--muted:#526570;--line:#dce4e6;--green:#087b62}*{box-sizing:border-box}body{margin:0;background:#f2f5f4;color:var(--ink);font:16px/1.55 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:40px 24px 70px}h1{font-size:clamp(28px,4vw,44px);line-height:1.15;margin:8px 0 20px}h2{margin:0;font-size:26px}h3{font-size:17px}a{color:#086852;overflow-wrap:anywhere}button,input,textarea{font:inherit}button{background:#087b62;color:white;border:0;padding:10px 16px;border-radius:7px;cursor:pointer}input,textarea{width:100%;border:1px solid #bbc9cc;border-radius:7px;padding:12px;background:white;color:var(--ink)}textarea{line-height:1.6;resize:vertical}label{display:block;font-size:14px;font-weight:600;margin:14px 0}.eyebrow{text-transform:uppercase;letter-spacing:.13em;color:var(--green);font-size:12px;font-weight:750}.muted{color:var(--muted);font-size:14px}.stats{display:flex;flex-wrap:wrap;gap:12px;margin:25px 0}.stat{background:white;border:1px solid var(--line);border-radius:10px;padding:15px 24px;min-width:155px}.stat b{display:block;font-size:28px}.prospect{margin:24px 0;padding:28px;border:1px solid var(--line);border-radius:14px;background:white}article header{display:flex;justify-content:space-between;gap:16px}.score{font-size:36px;font-weight:750;color:var(--green)}.score small{display:block;font-size:12px;color:var(--muted);text-align:right}.columns{display:grid;grid-template-columns:1fr 1fr;gap:32px}.issues{list-style:none;padding:0}.finding{border-left:3px solid var(--line);padding:10px 16px;margin:14px 0;background:#f8faf9}.tag{font-size:11px;font-weight:750;text-transform:uppercase;padding:4px 7px;border-radius:5px}.verified{background:#d9f2e6;color:#175c46}.potential{background:#fff0ce;color:#785113}.draft{background:#f3f7f6;padding:20px;border-radius:10px;align-self:start}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.6 ui-monospace,monospace}details{margin:12px 0}summary{cursor:pointer;font-weight:600}.review-item{background:white;border:1px solid var(--line);border-radius:10px;padding:18px}.copy-status{font-size:12px;margin-left:10px}.empty{padding:25px;border:1px dashed #9baeb2;border-radius:10px}.controls{max-width:500px}footer{margin-top:40px;font-size:12px;color:var(--muted)}@media(max-width:760px){main{padding:24px 16px}.prospect{padding:20px}.columns{grid-template-columns:1fr;gap:12px}.stat{min-width:130px;flex:1}h2{font-size:23px}}@media print{button,.controls{display:none}article{break-inside:avoid}.columns{display:block}textarea{height:300px}}
</style></head><body><main><p class="eyebrow">Fouse Digital / Daily prospect review</p><h1>Fix the path to the next inquiry.</h1><p>''' + e(report.get('date', '')) + ''' · Verified contact-path problems first. Ranking is a review aid, not a revenue forecast.</p><div class="stats"><div class="stat"><b>''' + e(report.get('qualified_today', '—')) + '''</b>qualified today / 10</div><div class="stat"><b>''' + str(len(report.get('new_leads', []))) + '''</b>new outreach drafts</div><div class="stat"><b>''' + str(len(report.get('review_queue', []))) + '''</b>need browser inspection</div><div class="stat"><b>''' + e(report.get('shortfall', '—')) + '''</b>daily shortfall</div></div><p class="muted">Discovery: ''' + e(discovery.get('source', 'unspecified')) + ' (' + e(discovery.get('status', 'unspecified')) + '). Saved pool age: ' + e(discovery.get('age_days', 'not used')) + ''' days.</p><p><strong>Drafts only.</strong> No messages, forms, appointment bookings or quote requests have been sent. Potential findings never become outreach claims.</p>''' + diagnostics + exclusions + '''<label class="controls">Find a prospect<input id="search" type="search" placeholder="Business name"></label><section id="prospects">''' + (''.join(cards) or '<p class="empty">No newly verified conversion-path prospects in this run. Technical signals and unconfirmed issues do not fill the quota.</p>') + '''</section><h2>Browser inspection queue</h2><p class="muted">These businesses have potential issues only. They have no outreach drafts and are not marked as qualified in the ledger.</p>''' + (''.join(queue) or '<p>No additional browser-review candidates recorded.</p>') + '''<footer>''' + e(report.get('attribution', '')) + '''<p>Analysis is limited to inspected public HTML and a small set of contact links. Bounded Chromium checks are recorded per prospect. Blocked or inconclusive behavior stays potential; form delivery and actual booking completion are never tested.</p></footer></main><script>
document.querySelector('#search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.prospect').forEach(c=>{c.hidden=!c.dataset.name.includes(q)})});document.querySelectorAll('.copy').forEach(b=>b.addEventListener('click',async()=>{const box=b.closest('.draft');const t=box.querySelector('textarea');try{await navigator.clipboard.writeText(t.value);box.querySelector('.copy-status').textContent='Copied.'}catch(e){t.focus();t.select();box.querySelector('.copy-status').textContent='Select Copy from your device menu.'}}));
</script></body></html>'''
